import base64
import json
import os
import re
import time
import uuid
from datetime import datetime, timezone

import boto3
from botocore.exceptions import ClientError

TABLE = os.environ['TABLE_NAME']
DDB = boto3.client('dynamodb')
IS_COLD = True
ENVIRONMENT_ID = str(uuid.uuid4())
