><p>A small cloud experiment exploring reliable bookings under concurrent demand.</p>\n<div class="grid"><section class="card"><h2>Book a demo appointment</h2><span class="badge">Synthetic data only</span><form id="booking">\n<label for="patient">Demo patient alias</label><input id="patient" value="Demo Patient" maxlength="80" required>\n<label for="doctor">Doctor</label><select id="doctor"><option value="dr-101">Dr. Meera Shah · General physician</option><option value="dr-102">Dr. Arjun Rao · Dermatology</option><option value="dr-103">Dr. Anaya Patel · Pediatrics</option></select>\n<label for="slot">Appointment time (your device timezone)</label><input id="slot" type="datetime-local" step="1800" required>\n<button id="submit" type="submit">Confirm demo booking</button><p class="hint">Fictional doctors. No real appointments, medical details, or patient data. Try submitting the same appointment twice.</p></form></section>\n<section class="card" aria-live="polite"><h2>Booking result</h2><div id="status" class="status">Ready when you are</div><p id="message">Choose an appointment and submit your booking.</p><pre id="result">Your response will appear here.</pre><p class="hint">A conflicting booking is rejected without replacing the first booking. Refreshing this page does not reset the database.</p></section></div>\n<footer>Academic proof of concept · Not affiliated with Practo · Public demo without authentication</footer></main>\n<script>\nconst el=id=>document.getElementById(id);const d=new Date(Date.now()+86400000);d.setMinutes(0,0,0);el(\'slot\').value=new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);\nel(\'booking\').addEventListener(\'submit\',async e=>{e.preventDefault();el(\'submit\').disabled=true;const t=performance.now();try{const r=await fetch(\'/book\',{method:\'POST\',headers:{\'content-type\':\'application/json\'},body:JSON.stringify({patient:el(\'patient\').value,doctor:el(\'doctor\').value,slot:new Date(el(\'slot\').value).toISOString()})});const j=await r.json();el(\'status\').textContent=r.status===201?\'Booking confirmed\':r.status===409?\'This slot is already booked\':\'Unable to book\';el(\'status\').className=\'status\'+(r.ok?\'\':\' error\');el(\'message\').textContent=r.status===201?\'Your demo appointment was saved.\':r.status===409?\'Choose another time. The original booking is protected.\':j.error||j.message||\'Please try again.\';el(\'result\').textContent=\'HTTP \'+r.status+\' · \'+Math.round(performance.now()-t)+\' ms round trip\\n\'+JSON.stringify(j,null,2);}catch(err){el(\'status\').textContent=\'Connection failed\';el(\'message\').textContent=err.message;}finally{el(\'submit\').disabled=false;}});\n</script></body></html>\n'


def lambda_handler(event, context):
    global IS_COLD
    cold, IS_COLD = IS_COLD, False
    started = time.perf_counter()
    rid = context.aws_request_id
    http = event.get('requestContext', {}).get('http', {})
    method, path = http.get('method'), event.get('rawPath', http.get('path', '/'))

    def response(status, payload):
        payload.update(cold_start=cold, request_id=rid, environment_id=ENVIRONMENT_ID,
                       handler_ms=round((time.perf_counter() - started) * 1000, 3))
        # No patient information or event body is logged.
        print(json.dumps({'event': 'request', 'request_id': rid, 'status': status,
                          'cold_start': cold, 'environment_id': ENVIRONMENT_ID,
                          'handler_ms': payload['handler_ms']}))
        return {'statusCode': status, 'headers': {
            'content-type': 'application/json', 'cache-control': 'no-store',
            'x-content-type-options': 'nosniff'}, 'body': json.dumps(payload)}

    if method == 'GET' and path == '/':
        return {'statusCode': 200, 'headers': {
            'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store',
            'x-content-type-options': 'nosniff', 'x-frame-options': 'DENY',
            'content-security-policy': "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'"
        }, 'body': HTML}
    if method == 'GET' and path == '/health':
        return response(200, {'status': 'ok', 'region': os.environ.get('AWS_REGION'),
                              'note': 'Function health only; booking tests verify the database.'})
    if method != 'POST' or path != '/book':
        return response(404, {'error': 'Route not found'})
    try:
        raw = event.get('body') or ''
        if len(raw) > 6000:
            return response(413, {'error': 'Request too large'})
        if event.get('isBase64Encoded'):
            raw = base64.b64decode(raw, validate=True).decode('utf-8')
        body = json.loads(raw)
        if not isinstance(body, dict):
            raise ValueError('JSON object required')
        patient, doctor, slot = (body.get(k) for k in ('patient', 'doctor', 'slot'))
        if not all(isinstance(v, str) and v.strip() for v in (patient, doctor, slot)):
            raise ValueError('patient, doctor and slot must be nonempty strings')
        patient, doctor, slot = patient.strip(), doctor.strip(), slot.strip()
        if len(patient) > 80 or not re.fullmatch(r'[A-Za-z0-9_-]{1,80}', doctor):
            raise ValueError('Patient: max 80 characters; doctor: letters, digits, hyphen, underscore, max 80')
        if len(slot) > 40:
            raise ValueError('Invalid slot')
        dt = datetime.fromisoformat(slot.replace('Z', '+00:00'))
        if dt.tzinfo is None or dt.utcoffset() is None:
            raise ValueError('Slot must include a timezone offset')
        dt = dt.astimezone(timezone.utc)
        if dt.second or dt.microsecond or dt.minute not in (0, 30):
            raise ValueError('Choose an exact half-hour slot')
        if dt <= datetime.now(timezone.utc):
            raise ValueError('Slot must be in the future')
        canonical = dt.isoformat(timespec='seconds').replace('+00:00', 'Z')
    except (ValueError, TypeError, UnicodeError) as exc:
        return response(400, {'error': str(exc)})

    key = doctor + '#' + canonical
    try:
        DDB.put_item(TableName=TABLE, Item={
            'slot_key': {'S': key}, 'doctor': {'S': doctor},
            'slot': {'S': canonical}, 'patient': {'S': patient},
            'booked_at': {'S': datetime.now(timezone.utc).isoformat()},
        }, ConditionExpression='attribute_not_exists(slot_key)')
        return response(201, {'status': 'booked', 'slot_key': key})
    except ClientError as exc:
        if exc.response['Error']['Code'] == 'ConditionalCheckFailedException':
            return response(409, {'status': 'already_booked', 'slot_key': key})
        print(json.dumps({'event': 'database_error', 'request_id': rid,
                          'code': exc.response['Error']['Code']}))
        return response(503, {'error': 'Database unavailable; retry later'})
